        return 'NO'
    if len(edges) < n - 1:
        return 'NO'

    from collections import defaultdict, deque

    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    # Check if the graph is a single cycle
    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True
    nodes_visited = 0

    while queue:
        node = queue.popleft()
        nodes_visited += 1
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    if nodes_visited != n:
        return 'NO'

    # Check for cycles
    cycle_count = 0
